/// What a human reads.
///
/// EVERY unread row is named with its line number. A count alone would be the wrong shape of
/// honesty: "3 rows not read" tells you the total is wrong without telling you where to look, and a
/// number that is wrong by an unknown amount is not usable for anything.
pub fn render_text(p: &Parsed) -> String {
    let mut out = String::new();
    out.push_str(&format!("{} · {}\n", p.institution.name(), p.profile));
    out.push_str(&format!("  {} transaction(s)\n", p.txns.len()));
    let net: i64 = p.txns.iter().map(|t| t.minor).sum();
    out.push_str(&format!("  net {}\n", crate::money::format_minor(net)));
    if p.rejected.is_empty() {
        out.push_str("  every row read\n");
    } else {
        out.push_str(&format!("  {} row(s) NOT read:\n", p.rejected.len()));
        for r in &p.rejected {
            out.push_str(&format!("    line {}: {}\n", r.line, r.reason));
        }
    }
    out
}

/// What another program reads. Carries the rejections too — a consumer that only saw `transactions`
/// would compute a total off a file it did not know was short.
pub fn render_json(p: &Parsed) -> serde_json::Value {
    serde_json::json!({
        "institution": p.institution.name(),
        "profile": p.profile,
        "transactions": p.txns.iter().map(|t| serde_json::json!({
            "date": t.date,
            "description": t.description,
            "minor": t.minor,
        })).collect::<Vec<_>>(),
        "rejected": p.rejected.iter().map(|r| serde_json::json!({
            "line": r.line,
            "reason": r.reason,
        })).collect::<Vec<_>>(),
    })
}


/// The inbox report, and what to do about each file.
///
/// SEPARATE FROM THE IO for the same reason `render_text` is: what this says is the whole product of
/// the verb, and a verb whose output nothing can assert on has no test.
pub fn render_inbox(files: &[inbox::InboxFile]) -> String {
    inbox::render(files)
}

/// Whether each connection could be fetched unattended right now.
///
/// `NeedsPerson` and `Blocked` are rendered DIFFERENTLY on purpose. One is the design working as
/// intended — you sign in, everything after is unattended — and the other is something to go and look
/// at. Printing both as "failed" would make the normal case alarming and hide the real one.
pub fn render_sessions(states: &[SessionState], connectors: &[&str], as_of: &str) -> String {
    let mut out = String::new();
    for id in connectors {
        let state = session::state_for(states, id);
        let verdict = session::may_fetch_unattended(&state, as_of, session::DEFAULT_TTL_HOURS);
        let (tag, reason) = match &verdict {
            FetchVerdict::Go => ("ready", verdict.reason().to_string()),
            FetchVerdict::NeedsPerson(r) => ("your turn", r.clone()),
            FetchVerdict::Blocked(r) => ("BLOCKED", r.clone()),
        };
        out.push_str(&format!("  {id} · {tag}\n      {reason}\n"));
    }
    out
}

fn store_path() -> Result<std::path::PathBuf, String> {
    let base = bsc_util::bsc_base_dir().ok_or_else(|| "no base dir ($HOME unset)".to_string())?;
    Ok(base.join("fin").join("sessions.json"))
}

fn load_states() -> Vec<SessionState> {
    let Ok(path) = store_path() else { return Vec::new() };
    let Ok(text) = std::fs::read_to_string(&path) else { return Vec::new() };
    serde_json::from_str::<serde_json::Value>(&text).map(|v| session::from_json(&v)).unwrap_or_default()
}

fn save_states(states: &[SessionState]) -> Result<(), String> {
    let path = store_path()?;
    if let Some(dir) = path.parent() {
        std::fs::create_dir_all(dir).map_err(|e| format!("cannot create {}: {e}", dir.display()))?;
    }
    std::fs::write(&path, serde_json::to_string_pretty(&session::to_json(states)).unwrap_or_default())
        .map_err(|e| format!("cannot write {}: {e}", path.display()))
}


/// The on-ramp.
///
/// EVERY FIGURE THIS SYSTEM CAN PRODUCE IS WAITING ON A FILE. Position, runway, what to pay first,
/// which call to make — all of it is arithmetic over transactions, and none of it exists until a
/// statement lands. So the highest-value thing the surface can do, before any analysis, is remove
/// every excuse between a person and that download: where the button is, what range to pick, what to
/// call the file, and what to run next.
///
/// The DATE RANGE guidance is not padding. Three whole months is the floor for an income projection,
/// and an annual charge cannot be detected inside twelve — so "as far back as it lets you" is a
/// materially better answer than the default range every one of these sites offers.
pub fn render_start(inbox: &std::path::Path) -> String {
    let mut out = String::new();
    out.push_str("Nothing here works until a statement lands. This is the whole setup.\n\n");
    out.push_str(&format!("  1. the inbox is  {}\n\n", inbox.display()));
    out.push_str("  2. download each account's CSV and drop it in there:\n\n");
    for i in [
        statement::Institution::Discover,
        statement::Institution::CapitalOne,
        statement::Institution::BankOfAmerica,
        statement::Institution::Chase,
    ] {
        out.push_str(&format!("       {:<16} {}\n", i.name(), i.export_path()));
        out.push_str(&format!("       {:<16} name it  {}-<anything>.csv\n\n", "", i.name()));
    }
    // The single highest-leverage instruction on the page.
    out.push_str("  3. pick the LONGEST date range offered — as far back as it lets you.\n");
    out.push_str("     three whole months is the FLOOR for an income projection, and a yearly\n");
    out.push_str("     charge cannot be found inside twelve. the default range on every one of\n");
    out.push_str("     these sites is shorter than what you want.\n\n");
    out.push_str("  4. then run:  bsc fin inbox --ingest\n\n");
    out.push_str("A file whose name does not start with one of those four is left alone rather than\n");
    out.push_str("guessed at — the wrong profile reads a date as an amount and says so confidently.\n");
    out
}


/// Every verb that exists, as prose, from the one place they are declared.
pub fn verb_list(prog: &str) -> String {
    let names: Vec<String> = COMMANDS.iter().map(|c| format!("`{prog} {}`", c.name)).collect();
    match names.split_last() {
        Some((last, rest)) if !rest.is_empty() => format!("{} or {last}", rest.join(", ")),
        Some((last, _)) => last.clone(),
        None => "nothing — this surface has no verbs".to_string(),
    }
}

