/// The registry AND its gaps, as one value — because a caller that got the accounts without knowing
/// what is missing from them would compute a confident number over a partial picture.
pub fn accounts_json(accounts: &[Account], rejected: &[String]) -> serde_json::Value {
    let (known, possible) = account::completeness(accounts);
    serde_json::json!({
        "accounts": account::all_to_json(accounts),
        "gaps": account::gaps(accounts).iter().map(|g| serde_json::json!({
            "account": g.account, "field": g.field, "blocks": g.blocks,
        })).collect::<Vec<_>>(),
        "known": known,
        "knowable": possible,
        "unreadable": rejected,
    })
}


/// What to run to declare an account a statement just revealed.
///
/// A READY COMMAND, not a description of one. The gap between "you should declare this" and a line
/// somebody can paste is where the loop between ingest and the registry actually breaks — and an
/// agent driving this has no hands to go and look up the field names.
pub fn declare_hint(id: &str, institution: &str, kind: crate::account::Kind) -> String {
    format!(
        "echo '{{\"id\":\"{id}\",\"institution\":\"{institution}\",\"kind\":\"{}\"}}' | bsc fin account set",
        kind.as_str()
    )
}


/// The value after a `--flag`, if it is there and is not itself another flag.
/// The flags that are a PRESENCE, not a name/value pair. Everything else consumes the token after
/// it, and this list is what tells the two apart.
///
/// It has to be enumerated because nothing in the argument text distinguishes them: `--json list`
/// and `--as-of list` look identical to a parser and mean opposite things.
const BOOLEAN_FLAGS: &[&str] = &["--json", "--ingest", "--all", "--established", "--snowball"];

/// The arguments that are actually POSITIONAL — flags removed, AND the value each flag consumes.
///
/// Dropping only the `--flag` tokens leaves every flag's VALUE in the list, where it lands one slot
/// further along and is read as something it is not. `bsc fin invoice --as-of 2026-07-10` put the
/// date where the subcommand goes and was answered with "unknown subcommand `2026-07-10`". The
/// other verbs escaped it by luck of position rather than by handling it, so the fix belongs here
/// and not in the arm that happened to notice.
fn positional_args(args: &[String]) -> Vec<&String> {
    let mut out = Vec::new();
    let mut skip = false;
    for a in args {
        if skip {
            skip = false;
            continue;
        }
        if a.starts_with("--") {
            skip = !BOOLEAN_FLAGS.contains(&a.as_str());
            continue;
        }
        out.push(a);
    }
    out
}

fn flag_value(args: &[String], flag: &str) -> Option<String> {
    let i = args.iter().position(|a| a == flag)?;
    args.get(i + 1).filter(|v| !v.starts_with("--")).cloned()
}

