/// Every transaction read so far, from the files themselves.
///
/// THE FILES ARE THE STORE. `processed/` holds every statement that has been claimed, and parsing is
/// deterministic — so re-reading them cannot drift from a second copy, because there is no second
/// copy to drift from. The account comes from the PROFILE that matched, not from the filename, so a
/// Chase card and a Chase chequing export do not collapse onto one id.
/// Every transaction read so far, and every statement PERIOD the exports carried.
///
/// THE FILES ARE THE STORE. `processed/` holds every statement that has been claimed, and parsing is
/// deterministic — so re-reading them cannot drift from a second copy, because there is no second
/// copy to drift from. The account comes from the PROFILE that matched, not from the filename, so a
/// Chase card and a Chase chequing export do not collapse onto one id.
///
/// A file whose export carried a running balance yields a period, and a period is what lets
/// `reconcile` actually gate rather than being a type nothing exercises.
type ReadStatements = (Vec<crate::txn::Txn>, Vec<reconcile::StatementPeriod>, Vec<String>);

pub fn read_all_statements() -> Result<ReadStatements, String> {
    let mut txns = Vec::new();
    let mut periods = Vec::new();
    let mut notes = Vec::new();
    for dir in [inbox::processed_dir(), inbox::inbox_dir()].into_iter().flatten() {
        for f in inbox::scan(&dir)? {
            let Ok(text) = std::fs::read_to_string(&f.path) else { continue };
            match statement::parse_csv(&text) {
                Ok(p) => {
                    let id = statement::suggested_account_id(&p);
                    let lifted: Vec<crate::txn::Txn> = p
                        .txns
                        .iter()
                        .map(|row| crate::txn::Txn::from_row(row, &id, crate::money::Currency::USD))
                        .collect();
                    if let (Some(b), Some(first), Some(last)) = (p.period, lifted.first(), lifted.last()) {
                        periods.push(reconcile::usd_period(&id, &first.date, &last.date, b.opening, b.closing));
                    } else {
                        notes.push(format!("{}: no running balance, so this file cannot be reconciled — a fact about the export, not a failure", f.name));
                    }
                    txns.extend(lifted);
                    if !p.rejected.is_empty() {
                        notes.push(format!("{}: {} row(s) unread — every total below is short by them", f.name, p.rejected.len()));
                    }
                }
                Err(e) => notes.push(format!("{}: NOT READ — {e}", f.name)),
            }
        }
    }
    txns.sort_by(|a, b| a.date.cmp(&b.date));
    Ok((txns, periods, notes))
}

/// Everything the analysis verbs stand on, built once.
///
/// Six verbs need the same four things — the transactions, a ledger that says whether they were
/// checked, the position that follows, and the notes explaining what could not be read. Each of them
/// assembled it inline until there were four copies, and a fifth would have been the one where the
/// reconcile silently differed from the others.
pub struct Analysis {
    pub txns: Vec<crate::txn::Txn>,
    pub ledger: reconcile::ReconciledLedger,
    pub position: position::Position,
    pub notes: Vec<String>,
}

/// Read every claimed statement and derive the position from it.
///
/// A REAL RECONCILE WHEN THE EXPORTS CARRIED BALANCES, and an honest unverified ledger when they did
/// not — never a reconcile that quietly passed because nothing checked it.
pub fn analysis(as_of: &str) -> Result<Analysis, String> {
    let usd = crate::money::Currency::USD;
    let (accounts, _) = load_accounts();
    let stored = load_balances();
    let (txns, periods, mut notes) = read_all_statements()?;
    let through = txns.last().map(|t| t.date.clone()).unwrap_or_else(|| as_of.to_string());
    // The statements' own closing figures ARE balances, so an export alone is enough to answer — a
    // declared account no longer has to be told what it holds. What a person typed wins on the same
    // day; see `balance::prefer_observed`.
    let balances = balance::latest_each(&balance::prefer_observed(&stored, &balance::from_periods(&periods)));
    let ledger = if periods.is_empty() {
        reconcile::unverified_ledger(&txns, &through, "no export carried a running balance, so there is nothing to check the transactions against")?
    } else {
        let r = reconcile::reconcile(&txns, &periods);
        match r.ledger {
            Some(l) => l,
            None => {
                for p in &r.problems {
                    notes.push(format!("RECONCILE: {}", p.detail));
                }
                for u in &r.uncovered {
                    notes.push(format!("RECONCILE: {} on {} belongs to no statement period", u.description, u.date));
                }
                reconcile::unverified_ledger(&txns, &through, "the statements did NOT reconcile — see the notes below")?
            }
        }
    };
    let position = position::position(&ledger, &accounts, &balances, usd);
    Ok(Analysis { txns, ledger, position, notes })
}

/// The position, rendered. Gaps are not a footnote — they are why a figure is missing.
/// Truncate to at most `n` CHARACTERS, never bytes.
///
/// `&s[..22]` panics when byte 22 lands inside a multi-byte character, and a statement description is
/// exactly where that arrives: a merchant with an accent, a currency symbol, a non-Latin name. The
/// crash would be in the RENDERER, so the analysis would be correct and the command would still die.
fn clip(s: &str, n: usize) -> String {
    if s.chars().count() <= n { s.to_string() } else { s.chars().take(n).collect() }
}

/// Drop a trailing " — <digits> due" from an action title.
///
/// The ported `brief` builds its titles in MINOR UNITS, faithfully to the TypeScript, which is right
/// for a JSON consumer and actively misleading in a terminal: "6000 due" printed beside a formatted
/// "60.00" reads as two different numbers a hundred times apart. The amount already has its own
/// column here, so the renderer drops the duplicate rather than the module changing units and
/// diverging from the other kit.
fn trim_minor_suffix(title: &str) -> &str {
    let Some(cut) = title.rfind(" — ") else { return title };
    let tail = &title[cut + " — ".len()..];
    match tail.strip_suffix(" due") {
        Some(n) if !n.is_empty() && n.chars().all(|c| c.is_ascii_digit()) => &title[..cut],
        _ => title,
    }
}

/// A short position, with the price that ends it at the top.
///
/// The call price leads because it decides the outcome: a short does not end when you are proved
/// right or wrong, it ends when the broker closes it. And the unreachable rows of the ladder are
/// PRINTED, marked, rather than trimmed — seeing that a 30% rise is past your exit is the point.
pub fn render_short(cap: &short::Capacity, shares: i64, rows: &[short::Outcome], compare: &[short::Exposure], carry: &short::Carry) -> String {
    let mut out = String::new();
    let m = |x: i64| crate::money::format_minor(x);
    out.push_str(&format!(
        "shorting {shares} share(s) at {} against {} of equity\n\n",
        m(cap.price.minor),
        m(cap.equity.minor)
    ));
    out.push_str(&format!(
        "  MARGIN CALL AT {}  — a rise of {:.1}% ends the position, whether or not you were right\n",
        m(cap.margin_call_price.minor),
        cap.headroom * 100.0
    ));
    out.push_str(&format!("  Regulation T allows at most {} shares ({}) on this equity\n", cap.max_shares, m(cap.max_position.minor)));
    if carry.borrow_apr > 0.0 || carry.days_held > 0 {
        out.push_str(&format!("  carry: {:.1}% borrow over {} day(s){}\n", carry.borrow_apr * 100.0, carry.days_held,
            if carry.dividends_per_share.minor > 0 { format!(", plus {} a share in dividends you owe", m(carry.dividends_per_share.minor)) } else { String::new() }));
    }

    out.push_str("\n  move      price        gross      carry          net    on equity\n");
    for o in rows {
        out.push_str(&format!(
            "  {:>+5.0}% {:>10} {:>12} {:>10} {:>12} {:>10.1}%  {}\n",
            o.move_pct * 100.0,
            m(o.at_price.minor),
            m(o.gross.minor),
            m(-(o.borrow_cost.minor + o.dividends_owed.minor)),
            m(o.net.minor),
            o.return_on_equity * 100.0,
            if o.reachable { "" } else { "PAST THE CALL — you are already out" }
        ));
    }

    if !compare.is_empty() {
        out.push_str("\n  the same view, three ways:\n");
        out.push_str("    vehicle          at risk       max loss      max gain   margin\n");
        for e in compare {
            out.push_str(&format!(
                "    {:<14}{:>12}{:>15}{:>14}{:>9}\n",
                e.vehicle.label(),
                m(e.capital_at_risk.minor),
                // ABSENT, not a big number — the price has no ceiling and a figure here would
                // invite somebody to size against it.
                e.max_loss.map(|l| m(l.minor)).unwrap_or_else(|| "UNBOUNDED".into()),
                m(e.max_gain.minor),
                if e.needs_margin { "yes" } else { "no" }
            ));
            out.push_str(&format!("      {}\n", e.note));
        }
    }

    if !cap.notes.is_empty() {
        out.push_str("\nWhat this is standing on:\n");
        for n in &cap.notes {
            out.push_str(&format!("  · {n}\n"));
        }
    }
    out
}

/// What an hour has to earn.
///
/// The offer assessment is printed BELOW the ladder rather than beside it, because the two answer
/// different questions: what you must charge, and whether a specific number on the table can get
/// there at all. Merging them reads as one recommendation and it is two facts.
pub fn render_rate(f: &rate::RateFloor, offers: &[rate::OfferVerdict], read_notes: &[String]) -> String {
    let mut out = String::new();
    let m = |x: i64| crate::money::format_minor(x);
    out.push_str(&format!("{}\n\n", rate::summarise(f)));
    out.push_str("  tier         needs/month     must bill      hourly     day rate\n");
    for t in &f.tiers {
        out.push_str(&format!(
            "  {:<12}{:>12}{:>14}{:>12}{:>13}\n",
            t.tier.label(),
            m(t.monthly_need.minor),
            m(t.must_bill_monthly.minor),
            m(t.hourly.minor),
            m(t.day_rate.minor)
        ));
    }

    if !offers.is_empty() {
        let offered = offers[0].offered;
        out.push_str(&format!("\n  at {} an hour:\n", m(offered.minor)));
        for o in offers {
            out.push_str(&format!(
                "    {:<12}{:>6.0}h of {:.0}h  {}\n",
                o.tier.label(),
                o.hours_needed,
                o.hours_available,
                if o.reachable { "reachable" } else { "OUT OF REACH at any hours" }
            ));
        }
        // The one that matters is whether it reaches CURRENT — the line below which new damage
        // starts. Printed as prose because it is the sentence somebody needs in a negotiation.
        if let Some(c) = offers.iter().find(|o| o.tier == crate::viable::Tier::Current) {
            out.push_str(&format!("\n  {}\n", c.why));
        }
    }

    out.push_str("\nWhat this is standing on:\n");
    for a in &f.assumptions {
        out.push_str(&format!("  · {a}\n"));
    }
    for w in &f.warnings {
        out.push_str(&format!("  · {w}\n"));
    }
    for n in read_notes {
        out.push_str(&format!("  · {n}\n"));
    }
    out
}

/// The simulation report — the instrument checked against worlds whose truth was set here.
///
/// The multiple-testing count goes LAST and is the part to read. Everything above it is the harness
/// behaving; that number is the reason the harness has to exist.
pub fn render_simulation(regimes: &[simulate::RegimeResult], mt: &simulate::MultipleTesting, bars: usize, bps: f64) -> String {
    let mut out = String::new();
    let pc = |x: f64| format!("{:.1}%", x * 100.0);
    out.push_str(&format!("SIMULATED DATA — {bars} bars per shape, costs at {bps} bps one way.\nNone of this is a market. The point is that the right answer is known in advance.\n"));

    for r in regimes {
        out.push_str(&format!("\n{}  {}\n", if r.matched { "OK  " } else { "MISS" }, r.shape.label()));
        out.push_str(&format!("     expected: {}\n", r.expectation));
        out.push_str(&format!("     observed: {}\n", r.observed));
        for e in r.results.iter().take(3) {
            out.push_str(&format!(
                "       {:<16}{:<20}{:>8} net  {:>8} hold  {:>7} maxDD\n",
                clip(&e.signal, 16),
                e.verdict.label(),
                e.net.map(|s| pc(s.total_return)).unwrap_or_else(|| "—".into()),
                e.benchmark.map(|s| pc(s.total_return)).unwrap_or_else(|| "—".into()),
                e.net.map(|s| pc(s.max_drawdown)).unwrap_or_else(|| "—".into()),
            ));
        }
    }

    out.push_str(&format!(
        "\n\nMULTIPLE TESTING — {} signals that are KNOWN to be worthless, on data KNOWN to be noise\n",
        mt.trials
    ));
    out.push_str(&format!("  best |t| among them          {:.2}\n", mt.best_t));
    out.push_str(&format!("  and it appeared to return    {}\n", pc(mt.best_return)));
    out.push_str(&format!("  conventional bar             {:.2}   → {} of {} \"significant\"\n", mt.naive_bar, mt.pass_naive, mt.trials));
    out.push_str(&format!("  bar for {} trials{}{:.2}   → {} of {}\n", mt.trials, " ".repeat(14usize.saturating_sub(mt.trials.to_string().len())), mt.honest_bar, mt.pass_honest, mt.trials));
    out.push_str(
        "\n  Every one of those signals is a coin flip and the series has no drift, so the true\n  answer is zero for all of them. Whatever cleared the conventional bar cleared it by\n  luck — which is exactly what happens to somebody sweeping parameters and reporting\n  the best result they found.\n",
    );
    out
}

/// What the battery found.
///
/// The CONTROL is printed with everything else rather than filtered out, because a mediocre result
/// read in isolation looks like something and read beside a coin flip does not. The t-statistic and
/// the bar it had to clear are printed together for the same reason — a number without its
/// threshold is a number somebody rounds up in their head.
pub fn render_backtest(reports: &[(String, Vec<crate::evaluate::Evaluation>, Vec<String>)], bps: f64) -> String {
    let mut out = String::new();
    let pc = |x: f64| format!("{:.1}%", x * 100.0);
    out.push_str(&format!("costs charged at {bps} bps one way, on every change in position\n"));

    for (symbol, evs, notes) in reports {
        out.push_str(&format!("\n{symbol}\n"));
        if evs.is_empty() {
            for n in notes {
                out.push_str(&format!("  · {n}\n"));
            }
            continue;
        }
        out.push_str("  signal            verdict                  net     hold      o/s        t   bar\n");
        for e in evs {
            let (net, bench, oos) = (
                e.net.map(|s| pc(s.total_return)).unwrap_or_else(|| "—".into()),
                e.benchmark.map(|s| pc(s.total_return)).unwrap_or_else(|| "—".into()),
                e.out_of_sample.map(|s| pc(s.total_return)).unwrap_or_else(|| "—".into()),
            );
            out.push_str(&format!(
                "  {:<16}  {:<20}{:>7}{:>9}{:>9}{:>9}{:>6.2}\n",
                clip(&e.signal, 16),
                e.verdict.label(),
                net,
                bench,
                oos,
                e.t_stat.map(|t| format!("{t:.2}")).unwrap_or_else(|| "—".into()),
                e.t_required
            ));
        }
        // The reason for the TOP result only — the rest are visible above and a wall of prose
        // buries the table that is doing the work.
        if let Some(top) = evs.first() {
            out.push_str(&format!("\n  {}: {}\n", top.signal, top.why));
        }
        let control = evs.iter().find(|e| e.signal == "null-control");
        if let (Some(c), Some(top)) = (control, evs.first()) {
            if top.signal != "null-control" {
                // The only part that is evidence is the DIFFERENCE between a candidate and a coin.
                out.push_str(&format!(
                    "  the coin flip scored {} net for comparison — the gap is the only part that is evidence\n",
                    c.net.map(|s| pc(s.total_return)).unwrap_or_else(|| "—".into())
                ));
            }
        }
        for n in notes {
            out.push_str(&format!("  · {n}\n"));
        }
        let mut seen: Vec<&str> = Vec::new();
        for e in evs {
            for c in &e.caveats {
                if !seen.contains(&c.as_str()) {
                    seen.push(c);
                    out.push_str(&format!("  · {c}\n"));
                }
            }
        }
    }
    out
}

/// The brief — one ranked list of what to do.
///
/// The two tiers are printed as two lists and never merged, because merging them is the mistake:
/// a payment due Friday is not comparable to a grant by any rate. Within the second, the order is
/// PER HOUR, so a ten-minute phone call can and does outrank a five-figure opportunity.
pub fn render_brief(b: &brief::Brief, read_notes: &[String]) -> String {
    let mut out = String::new();
    let m = |x: i64| crate::money::format_minor(x);
    out.push_str(&format!("{}\n", b.headline));

    if !b.do_not_miss.is_empty() {
        out.push_str("\nDO NOT MISS — dated, and no rate makes these comparable to the list below\n");
        for a in &b.do_not_miss {
            out.push_str(&format!(
                "  {:<12}{:>11}  {}{}\n",
                a.by.clone().unwrap_or_else(|| "no date".into()),
                a.worth.map(|w| m(w.minor)).unwrap_or_default(),
                clip(trim_minor_suffix(&a.title), 52),
                if a.provisional { "  (provisional)" } else { "" }
            ));
        }
    }

    if !b.best_return.is_empty() {
        out.push_str("\nBEST RETURN — ranked by what it is worth PER HOUR of your effort\n");
        for a in &b.best_return {
            let per = a.per_hour.map(|p| format!("{}/h", m(p.minor))).unwrap_or_else(|| "—".into());
            let hrs = a.effort_hours.map(|h| format!("{h}h")).unwrap_or_else(|| "—".into());
            out.push_str(&format!(
                "  {:>12}  {:>7}  {:>11}   {}\n",
                per,
                hrs,
                a.worth.map(|w| m(w.minor)).unwrap_or_default(),
                clip(&a.title, 46)
            ));
            // The BASIS is printed with the number: without it, "a year if granted" and "a one-off"
            // read as the same kind of money and the comparison above is meaningless.
            if let Some(basis) = a.worth_basis {
                out.push_str(&format!("                                       {basis}\n"));
            }
        }
        out.push_str(&format!(
            "\n  {} in total if every one lands, over {} hour(s) — CONTINGENT, all of it\n",
            m(brief::total_if_everything_lands(b).minor),
            brief::total_effort_hours(b)
        ));
    }

    if !b.blocked.is_empty() {
        out.push_str("\nBLOCKED — worth unblocking, because one fix usually opens several\n");
        for a in &b.blocked {
            out.push_str(&format!("  {}\n    blocked by: {}\n", clip(&a.title, 60), a.blocked_by.clone().unwrap_or_default()));
        }
    }

    if let Some(next) = brief::next_action(b) {
        out.push_str(&format!("\nNEXT: {}\n", next.title));
    }

    if !b.absent.is_empty() {
        // The difference between "nothing to do" and "nothing looked".
        out.push_str("\nNot looked at — these contributed NOTHING rather than zero:\n");
        for x in &b.absent {
            out.push_str(&format!("  · {x}\n"));
        }
    }
    if !b.caveats.is_empty() || !read_notes.is_empty() {
        out.push_str("\nWhat this is standing on:\n");
        for c in &b.caveats {
            out.push_str(&format!("  · {c}\n"));
        }
        for n in read_notes {
            out.push_str(&format!("  · {n}\n"));
        }
    }
    out
}

/// The income ladder — four tiers, on the WORST month.
///
/// The tiers are printed in order with what each one gives up, because the trade is the answer: a
/// reader who sees only "survival: 2460.00" does not know they just agreed to cancel everything.
pub fn render_viable(v: &viable::ViableIncome, read_notes: &[String]) -> String {
    let mut out = String::new();
    let m = |x: i64| crate::money::format_minor(x);
    let gap = v.gaps.as_ref().and_then(|gs| gs.iter().find(|g| g.tier == viable::Tier::Current));
    let verdict = match gap {
        None => String::new(),
        Some(g) if g.clears => " — the low income band already clears it".to_string(),
        Some(g) => format!(" — the low income band is short by {}", m(g.shortfall.minor)),
    };
    out.push_str(&format!(
        "{} a month keeps everything current, measured on {} — the worst month, not the average{}\n\n",
        m(v.headline.worst_month.minor),
        v.headline.worst_month_name,
        verdict
    ));
    out.push_str("  tier         usual month    WORST month   shortfall\n");
    for t in &v.tiers {
        let gap = v.gaps.as_ref().and_then(|gs| gs.iter().find(|g| g.tier == t.tier));
        let short = match gap {
            None => String::new(),
            Some(g) if g.clears => "clears".to_string(),
            Some(g) => m(g.shortfall.minor),
        };
        out.push_str(&format!("  {:<12}{:>12}   {:>12}   {:>9}\n", t.tier.label(), m(t.typical_month.minor), m(t.worst_month.minor), short));
    }
    out.push_str(&format!("\n  the worst month is {}\n", v.headline.worst_month_name));

    // What each tier GIVES UP is the half a bare number hides.
    for t in &v.tiers {
        if t.excludes.is_empty() {
            continue;
        }
        out.push_str(&format!("\n  {} gives up:\n", t.tier.label()));
        for e in &t.excludes {
            out.push_str(&format!("    · {e}\n"));
        }
    }

    if !viable::ladder_is_ordered(v) {
        // Stated rather than silently rendered: a ladder out of order means the tiers were built
        // from figures that do not compose, and every number above is suspect.
        out.push_str("\n  WARNING: the ladder is out of order — a tier costs less than the one below it\n");
    }
    out.push_str("\nWhat this is standing on:\n");
    for n in &v.notes {
        out.push_str(&format!("  · {n}\n"));
    }
    for n in read_notes {
        out.push_str(&format!("  · {n}\n"));
    }
    out
}

/// Where this month's spare money goes.
///
/// The allocations print IN ORDER, because the order IS the recommendation — and each carries its
/// own reason, so a reader can disagree with the rule rather than only with the number.
pub fn render_priority(p: &priority::Priority, discretionary: i64, read_notes: &[String]) -> String {
    let mut out = String::new();
    let m = |x: i64| crate::money::format_minor(x);
    out.push_str(&format!(
        "{} a month is genuinely spare — the WORST month's net, not a good one\n  (discretionary spending taken as {} a month)\n\n",
        m(p.available.minor),
        m(discretionary)
    ));
    for al in &p.allocations {
        out.push_str(&format!("  {:<9}{:>12}   {}\n", al.kind.label(), m(al.amount.minor), al.label));
        out.push_str(&format!("            {}\n", al.reason));
    }
    out.push_str(&format!("\n  total this month  {}\n", m(priority::total_commitment(p).minor)));
    if p.lump_available.minor > 0 {
        // A ONE-OFF, kept separate from the monthly figure so the two are not added by accident.
        out.push_str(&format!("  liquid above the buffer, available as a ONE-OFF: {}\n", m(p.lump_available.minor)));
    }
    if !p.order.is_empty() {
        out.push_str(&format!("\n  the order after this one: {}\n", p.order.join(" → ")));
    }
    if !p.warnings.is_empty() || !read_notes.is_empty() {
        out.push_str("\nWhat this is standing on:\n");
        for w in &p.warnings {
            out.push_str(&format!("  · {w}\n"));
        }
        for n in read_notes {
            out.push_str(&format!("  · {n}\n"));
        }
    }
    out
}

/// Where the money actually goes.
///
/// The two EXCLUSIONS lead, because they are the reason this figure differs from a naive sum of
/// outflows — and a reader who does not know they happened will think the number is wrong.
pub fn render_spending(a: &spending::SpendingAnalysis, read_notes: &[String]) -> String {
    let mut out = String::new();
    let m = |x: i64| crate::money::format_minor(x);
    if a.outflows.is_empty() {
        out.push_str("no outflows in what has been read\n");
        for n in read_notes {
            out.push_str(&format!("  · {n}\n"));
        }
        return out;
    }
    out.push_str(&format!(
        "{} → {} · {} whole month(s)\n\n  fixed     {} a month — standing charges, already on the calendar\n  variable  {} a month — what an ordinary month actually costs\n",
        a.from, a.to, a.months_observed, m(a.fixed_monthly.minor), m(a.variable_monthly.minor)
    ));
    if !a.categories.is_empty() {
        out.push_str("\n  where the money goes, biggest first:\n");
        for c in &a.categories {
            out.push_str(&format!("    {:<16}{:>12}   {:>10} in a usual month\n", c.category, m(c.total.minor), m(c.typical_month.minor)));
        }
    }
    if !a.uncategorised.is_empty() {
        out.push_str(&format!("\n  {} outflow(s) matched no rule — listed, NOT bucketed as \"other\":\n", a.uncategorised.len()));
        for t in &a.uncategorised {
            out.push_str(&format!("    {} {:<28}{:>10}\n", t.date, clip(&t.description, 28), m(-t.amount.minor)));
        }
    }
    out.push_str("\nWhat was left out, and why:\n");
    for n in &a.notes {
        out.push_str(&format!("  · {n}\n"));
    }
    for n in read_notes {
        out.push_str(&format!("  · {n}\n"));
    }
    out
}

/// Which debt first — and what the second answer costs.
///
/// Both plans are printed. This module has no opinion about which one a person should run: the
/// avalanche always pays less interest and the snowball always clears an account sooner, and only
/// the person paying can say which of those they need.
pub fn render_payoff(c: &payoff::Comparison, skipped: &[String], notes: &[String]) -> String {
    let mut out = String::new();
    let m = |x: i64| crate::money::format_minor(x);
    let line = |p: &payoff::Plan| format!(
        "  {:<10} {:>3} months · {} interest · clears in the order {}\n",
        p.strategy.label(), p.months, m(p.total_interest.minor), p.order.join(" → ")
    );
    out.push_str(&line(&c.avalanche));
    out.push_str(&line(&c.snowball));

    out.push('\n');
    if c.extra_interest.minor == 0 && c.extra_months == 0 {
        out.push_str("  the two strategies agree here — the smallest debt is also the dearest one\n");
    } else {
        out.push_str(&format!(
            "  snowball costs {} more in interest and {} more month(s),\n  and clears its FIRST debt {} month(s) sooner\n",
            m(c.extra_interest.minor), c.extra_months, c.first_cleared_sooner
        ));
        out.push_str("  Neither is chosen for you: one is cheaper, the other is easier to keep going.\n");
    }

    if !skipped.is_empty() || !notes.is_empty() {
        out.push_str("\nWhat this is standing on:\n");
        for s in skipped {
            out.push_str(&format!("  · {s}\n"));
        }
        for n in notes {
            out.push_str(&format!("  · {n}\n"));
        }
    }
    out
}

/// How long the money lasts — on the LOW band, and saying so.
///
/// The headline is deliberately the pessimistic scenario. A runway on expected income is right on
/// average and useless in the case that matters, so the other two are shown as context BENEATH it
/// rather than offered as alternatives to quote.
pub fn render_runway(r: &runway::Runway, p: &projection::IncomeProjection, c: &obligations::ObligationCalendar, notes: &[String]) -> String {
    let mut out = String::new();
    let m = |x: i64| crate::money::format_minor(x);

    if r.headline.months.is_empty() {
        out.push_str(&format!("{}\n", runway::summarise(r)));
        for x in &r.problems {
            out.push_str(&format!("  · {x}\n"));
        }
        for n in notes {
            out.push_str(&format!("  · {n}\n"));
        }
        return out;
    }

    out.push_str(&format!("{}\n\n", runway::summarise(r)));
    out.push_str(&format!("  starting liquid  {}\n\n", m(r.starting_liquid.minor)));
    out.push_str("  month      opening       income   obligations   discretionary       closing\n");
    for x in &r.headline.months {
        out.push_str(&format!(
            "  {:<9}{:>11}  {:>11}   {:>11}     {:>11}   {:>11}{}\n",
            x.month,
            m(x.opening.minor),
            m(x.income.minor),
            m(x.obligations.minor),
            m(x.discretionary.minor),
            m(x.closing.minor),
            if x.shortfall.is_some() { "  SHORT" } else { "" },
        ));
    }

    if !runway::survives_horizon(&r.headline) {
        out.push_str(&format!(
            "\n  {} a month more closes it — {} over a year\n",
            m(r.headline.monthly_gap.minor),
            m(runway::annual_gap(r).minor)
        ));
    }
    // The other two scenarios are CONTEXT, shown as the gap each would need rather than as a length
    // of runway — a reader who sees "expected: 11 months" will quote that number.
    out.push_str(&format!(
        "\n  if income comes in at expected  {} a month short · at high  {} a month short\n",
        m(r.expected.monthly_gap.minor),
        m(r.high.monthly_gap.minor)
    ));

    if let Some(h) = obligations::heaviest_window(c, 7) {
        out.push_str(&format!("\n  heaviest week  {} → {}  {}\n", h.from, h.to, m(h.total.minor)));
    }

    out.push_str("\nWhat this is standing on:\n");
    for a in &p.assumptions {
        out.push_str(&format!("  · {a}\n"));
    }
    for x in &r.problems {
        out.push_str(&format!("  · {x}\n"));
    }
    for x in &c.notes {
        out.push_str(&format!("  · {x}\n"));
    }
    for n in notes {
        out.push_str(&format!("  · {n}\n"));
    }
    out
}

/// The standing charges, ANNUALISED.
///
/// The annual figure leads every line because that is the one that prompts action: "$14.99" reads as
/// nothing and "$179.88 a year" reads as a decision. Same charge.
///
/// A LAPSED charge is shown rather than filtered — it either stopped or is about to land, and those
/// want opposite responses, so the reader decides which.
pub fn render_recurring(rs: &[recurring::Recurring], live_total: crate::money::Money, txns: &[crate::txn::Txn], notes: &[String]) -> String {
    let mut out = String::new();
    if rs.is_empty() {
        // Nothing found is TWO different situations, and saying which one costs a line.
        out.push_str(if txns.is_empty() {
            "no transactions read yet — `bsc fin inbox --ingest` first\n"
        } else {
            "no repeating charge found in what has been read\n"
        });
        for n in notes {
            out.push_str(&format!("  · {n}\n"));
        }
        return out;
    }
    out.push_str(&format!("{} standing charge(s) · {} a year, live\n\n", rs.len(), crate::money::format_minor(live_total.minor)));
    for r in rs {
        out.push_str(&format!(
            "  {:>12} /yr  {:<22} {:<10} {:>10} each  {}\n",
            crate::money::format_minor(r.annualised.minor),
            // The LABEL, not the key — a person recognises "NETFLIX.COM", not "netflix".
            clip(&r.label, 22),
            r.cadence.label(),
            crate::money::format_minor(r.typical.minor),
            if r.lapsed { "LAPSED — cancelled, or about to hit" } else { "" },
        ));
        // Both scores are reported whenever either is soft. A utility recurs while its amount moves,
        // and hiding that would hide the charge rather than the uncertainty.
        if r.regularity < 0.9 || r.amount_stability < 0.9 {
            out.push_str(&format!(
                "               regularity {:.2} · amount stability {:.2} · {} seen since {}\n",
                r.regularity, r.amount_stability, r.occurrences, r.first_seen
            ));
        }
    }
    for n in notes {
        out.push_str(&format!("\n  · {n}\n"));
    }
    out
}

/// What arrives — and the WORST month, which is the number a plan has to survive.
///
/// The worst month leads. An average income reads as more certain than it is, and every downstream
/// question (runway, what payment is sustainable, whether a transfer is safe) turns on the low
/// months rather than the typical one.
pub fn render_income(a: &income::IncomeAnalysis, expected: crate::money::Money, notes: &[String]) -> String {
    let mut out = String::new();
    if a.sources.is_empty() && a.one_off.is_empty() {
        out.push_str("no money arriving in what has been read\n");
        for n in notes {
            out.push_str(&format!("  · {n}\n"));
        }
        return out;
    }
    out.push_str(&format!(
        "worst month {} · usual {} · best {} — over {} whole month(s)\n\n",
        crate::money::format_minor(a.worst_month.minor),
        crate::money::format_minor(a.typical_month.minor),
        crate::money::format_minor(a.best_month.minor),
        a.months_observed,
    ));
    for s in &a.sources {
        out.push_str(&format!(
            "  {:<22} {:<12} {:>12} /mo  {} · low {}\n",
            clip(&s.label, 22),
            s.cadence.label(),
            crate::money::format_minor(s.monthly_equivalent.minor),
            s.stability.label(),
            crate::money::format_minor(s.low.minor),
        ));
    }
    if !a.sources.is_empty() {
        out.push_str(&format!("\n  expected  {} a month from repeating sources\n", crate::money::format_minor(expected.minor)));
    }
    if !a.one_off.is_empty() {
        // NOT folded into the expectation. A tax refund is not income you can plan on receiving again.
        out.push_str(&format!("\n  {} one-off receipt(s), NOT counted as income you can plan on:\n", a.one_off.len()));
        for t in &a.one_off {
            out.push_str(&format!("    {} {:<26} {}\n", t.date, t.description, crate::money::format_minor(t.amount.minor)));
        }
    }
    // Coverage is stated rather than implied. Two months is not an income pattern, and the figure
    // above reads exactly the same whether it rests on two months or twenty.
    if a.months_observed < 3 {
        out.push_str(&format!("\n  · {} whole month(s) is too thin to call a pattern — these figures will move\n", a.months_observed));
    }
    for n in notes {
        out.push_str(&format!("  · {n}\n"));
    }
    out
}

pub fn render_position(p: &position::Position) -> String {
    let mut out = String::new();
    out.push_str(&format!("as of {} · {}\n\n", p.as_of, p.provenance));
    for a in &p.accounts {
        let util = a.utilisation.map(|u| format!("{}% used", (u * 100.0).round())).unwrap_or_else(|| "utilisation unknown".into());
        out.push_str(&format!(
            "  {:<18} {:<10} {:>12}   {}\n",
            a.account,
            a.kind.as_str(),
            crate::money::format_minor(a.balance.minor),
            if a.is_debt { util } else { String::new() }
        ));
    }
    out.push_str(&format!("\n  net worth  {}\n", crate::money::format_minor(p.net_worth.minor)));
    out.push_str(&format!("  liquid     {}\n", crate::money::format_minor(p.liquid.minor)));
    out.push_str(&format!("  owed       {}\n", crate::money::format_minor(p.total_debt.minor)));
    if p.total_debt.minor > 0 {
        out.push_str(&format!(
            "  costing    {} a day · {} a year at these rates\n",
            crate::money::format_minor(p.daily_interest.minor),
            crate::money::format_minor(position::annual_interest_cost(p).minor)
        ));
    }
    if !p.problems.is_empty() {
        out.push_str("\nWhat this is standing on:\n");
        for x in &p.problems {
            out.push_str(&format!("  · {x}\n"));
        }
    }
    out
}

/// The receivables ledger. Outstanding first, because that is the money not yet in the account.
///
/// The AMBIGUOUS section is deliberately above the matched one. A matched credit needs no attention;
/// a credit that fits two invoices needs a decision, and burying it under a list of settled rows is
/// how it stops being made.
pub fn render_invoices(
    settlements: &[invoice::Settlement],
    buckets: &[invoice::AgeBucket],
    m: &invoice::MatchResult,
    priced: &[invoice::Priced],
    as_of: &str,
) -> String {
    let mut out = String::new();
    let fm = crate::money::format_minor;
    out.push_str(&format!("Receivables as of {as_of}\n\n"));

    let owed: i64 = settlements.iter().filter(|s| s.state.is_outstanding()).map(|s| s.outstanding.minor).sum();
    if settlements.is_empty() {
        out.push_str("  No invoice has been issued yet.\n");
        out.push_str("  Raise one:  bsc fin invoice new INV-001 \"Client Name\" 2400.00 --due 2026-07-01\n");
        return out;
    }
    out.push_str(&format!("  Outstanding  {:>12}\n", fm(owed)));
    let received: i64 = m.matched.iter().map(|p| p.amount.minor).sum();
    out.push_str(&format!("  Received     {:>12}   across {} matched credit(s)\n\n", fm(received), m.matched.len()));

    if !m.ambiguous.is_empty() {
        out.push_str("  NEEDS A DECISION — these credits fit more than one invoice equally:\n");
        for a in &m.ambiguous {
            out.push_str(&format!("    {}  {:>12}  {}\n", a.date, fm(a.amount.minor), clip(&a.description, 34)));
            out.push_str(&format!("      could be: {}\n", a.candidates.join(" or ")));
        }
        out.push('\n');
    }

    let live: Vec<&invoice::Settlement> = settlements.iter().filter(|s| s.state.is_outstanding()).collect();
    if !live.is_empty() {
        out.push_str("  Owed\n");
        for s in &live {
            out.push_str(&format!(
                "    {:<14} {:<20} {:>12}  {}\n",
                clip(&s.invoice, 13),
                clip(&s.client, 19),
                fm(s.outstanding.minor),
                s.state.label()
            ));
        }
        out.push('\n');
    }

    let aged: Vec<&invoice::AgeBucket> = buckets.iter().filter(|b| !b.invoices.is_empty()).collect();
    if !aged.is_empty() {
        out.push_str("  Ageing\n");
        for b in aged {
            out.push_str(&format!("    {:<10} {:>12}   {}\n", b.label, fm(b.total.minor), b.invoices.join(", ")));
        }
        out.push('\n');
    }

    // TAX IS SHOWN ONLY WHERE IT IS NOT A SETTLED ZERO. A line per exempt invoice would bury the
    // two rows that need an action under a column of "exempt", which is the shape that stops a
    // report being read.
    let notable: Vec<&invoice::Priced> = priced.iter().filter(|p| !matches!(p.tax, invoice::TaxOutcome::None { .. })).collect();
    let exempt = priced.len() - notable.len();
    if !priced.is_empty() {
        out.push_str("  Tax\n");
        for p in &notable {
            match &p.tax {
                invoice::TaxOutcome::Charged { bps, amount, .. } => {
                    out.push_str(&format!("    {:<14} {:>12}  at {}\n", clip(&p.invoice, 13), fm(amount.minor), format_bps(*bps)));
                }
                invoice::TaxOutcome::Undetermined { what, where_to } => {
                    out.push_str(&format!("    {:<14} {:>12}  {}\n", clip(&p.invoice, 13), "UNDETERMINED", what));
                    out.push_str(&format!("      {where_to}\n"));
                }
                invoice::TaxOutcome::None { .. } => {}
            }
        }
        if exempt > 0 {
            let reason = priced
                .iter()
                .find_map(|p| match &p.tax {
                    invoice::TaxOutcome::None { reason, .. } => Some(reason.clone()),
                    _ => None,
                })
                .unwrap_or_default();
            out.push_str(&format!("    {exempt} invoice(s) carry none — {reason}\n"));
        }
        out.push('\n');
    }

    if !m.unexplained.is_empty() {
        out.push_str("  Arrived, belongs to no invoice\n");
        for t in &m.unexplained {
            out.push_str(&format!("    {}  {:>12}  {}\n", t.date, fm(t.amount.minor), clip(&t.description, 34)));
        }
        out.push('\n');
    }

    for n in &m.notes {
        out.push_str(&format!("  · {n}\n"));
    }
    out
}

/// Where you are, and what it asks of you.
///
/// Every figure prints WITH its source, because the standing caveat — nothing here has been checked
/// against those sources by a person — is only actionable if the source is on the same line.
pub fn render_where(
    chain: &[jurisdiction::Place],
    obligations: &[jurisdiction::Obligation],
    sales: &Result<(i64, Vec<jurisdiction::Rate>), String>,
    income: &[jurisdiction::Rate],
    as_of: &str,
) -> String {
    let mut out = String::new();
    let names: Vec<&str> = chain.iter().rev().map(|p| p.name).collect();
    out.push_str(&format!("{}\n", names.join(" › ")));
    out.push_str(&format!("as of {as_of}\n\n"));

    out.push_str("  Rates\n");
    match sales {
        Ok((bps, found)) => {
            out.push_str(&format!("    sales tax        {:>7}   ", format_bps(*bps)));
            out.push_str(&format!("{}\n", found.iter().map(|r| format!("{} {}", r.place, format_bps(r.bps))).collect::<Vec<_>>().join(" + ")));
        }
        Err(e) => out.push_str(&format!("    sales tax        REFUSED — {e}\n")),
    }
    if income.is_empty() {
        out.push_str("    income tax       NOT KNOWN for this date — a rate here would be a guess, and this is an input to a return\n");
    } else {
        for r in income {
            out.push_str(&format!("    income tax       {:>7}   {}{}\n", format_bps(r.bps), r.place, r.to.map(|t| format!(" (through {t})")).unwrap_or_default()));
        }
    }
    out.push('\n');

    if !obligations.is_empty() {
        out.push_str("  What this place requires\n");
        for o in obligations {
            let cost = match o.cost_minor {
                Some(0) => "free".to_string(),
                Some(c) => crate::money::format_minor(c),
                // NOT rendered as a number, because it is not one.
                None => "varies".to_string(),
            };
            let due = jurisdiction::next_due(o.cadence, as_of).map(|d| format!("next {d}")).unwrap_or_else(|| "once".to_string());
            out.push_str(&format!("    {:<32} {:>9}  {}\n", clip(o.name, 31), cost, due));
            out.push_str(&format!("      {}\n", o.required_when));
            out.push_str(&format!("      → {}\n", o.authority));
        }
        out.push('\n');
    }

    out.push_str("  NOTHING HERE HAS BEEN CHECKED AGAINST ITS SOURCE BY A PERSON, and rates change on a\n");
    out.push_str("  schedule. Run `bsc fin where sources` and verify before anything is filed. This is not\n");
    out.push_str("  tax advice and it files nothing.\n");
    out
}

/// Basis points as a percentage, without a float in the path.
pub fn format_bps(bps: i64) -> String {
    let sign = if bps < 0 { "-" } else { "" };
    let a = bps.abs();
    // 5.19% and 6.00% both read correctly; trailing zeros are kept so a column lines up.
    format!("{sign}{}.{:02}%", a / 100, a % 100)
}

/// The tax year. Ordered so the number you act on — what to set aside — is reachable, and the
/// things this cannot tell you are not a footnote.
pub fn render_tax(y: &taxyear::TaxYear, p: &taxyear::YearParams, harbour: (crate::money::Money, &str)) -> String {
    let fm = crate::money::format_minor;
    let mut out = String::new();
    out.push_str(&format!("Tax year {} · {} filer\n\n", y.year, y.status.key()));

    out.push_str(&format!("  Revenue (cash basis)   {:>12}   what ARRIVED in {}\n", fm(y.revenue.minor), y.year));
    match y.expense_basis {
        taxyear::ExpenseBasis::Declared => out.push_str(&format!("  Expenses declared      {:>12}\n", fm(y.expenses.minor))),
        // Not "0.00" — that would read as a fact about the business rather than a gap in the input.
        taxyear::ExpenseBasis::Absent => out.push_str(&format!("  Expenses declared      {:>12}\n", "NONE GIVEN")),
    }
    out.push_str(&format!("  Net profit             {:>12}\n\n", fm(y.net_profit.minor)));

    let se = &y.se;
    out.push_str(&format!("  Self-employment tax    {:>12}\n", fm(se.total.minor)));
    if se.total.minor > 0 {
        out.push_str(&format!("    net earnings         {:>12}   92.35% of profit — the base, not the profit\n", fm(se.net_earnings.minor)));
        out.push_str(&format!("    Social Security      {:>12}   12.4%{}\n", fm(se.social_security.minor), if se.cap_bound { format!(", capped at {}", fm(p.ss_wage_base_minor)) } else { String::new() }));
        out.push_str(&format!("    Medicare             {:>12}   2.9%, no ceiling\n", fm(se.medicare.minor)));
        if se.additional_medicare.minor > 0 {
            out.push_str(&format!("    extra Medicare       {:>12}   0.9% above the {} threshold\n", fm(se.additional_medicare.minor), y.status.key()));
        }
        out.push_str(&format!("    half is deductible   {:>12}   against INCOME tax — it does not reduce the line above\n", fm(se.deductible_half.minor)));
    }
    out.push('\n');

    match y.set_aside {
        Some(a) => {
            out.push_str(&format!("  SET ASIDE              {:>12}   self-employment tax plus YOUR income-tax estimate\n", fm(a.minor)));
            if y.revenue.minor > 0 {
                // The rate is what makes it a habit rather than a year-end shock.
                let pct = a.minor.saturating_mul(1000) / y.revenue.minor;
                out.push_str(&format!("                                        that is {}.{}% of every dollar that comes in\n", pct / 10, pct % 10));
            }
        }
        None => out.push_str("  SET ASIDE                       —   pass --income-rate to get this number\n"),
    }
    out.push_str(&format!("  Quarterly safe harbour {:>12}   90% of the self-employment tax above\n\n", fm(harbour.0.minor)));

    out.push_str("  Read this before using any figure above\n");
    for n in se.notes.iter().chain(y.notes.iter()) {
        out.push_str(&format!("    · {n}\n"));
    }
    out.push_str(&format!("    · {}\n", harbour.1));
    out.push_str(&format!("    · the {} wage base is from: {}\n", p.year, p.source));
    if !p.note.is_empty() {
        out.push_str(&format!("    · {}\n", p.note));
    }
    out.push_str("    · nothing here has been checked against its source by a person, and this files nothing\n");
    out
}

/// The hurdle. The recommendation is LAST because it only means anything after the numbers above
/// it, and it is the only line most readers will act on.
pub fn render_hurdle(
    e: &hurdle::Expectation,
    b: &hurdle::Buffer,
    ladder: &[hurdle::Hurdle],
    next: &hurdle::NextDollar,
    as_of: &str,
) -> String {
    let fm = crate::money::format_minor;
    let mut out = String::new();
    out.push_str(&format!("The hurdle · as of {as_of}\n\n"));

    out.push_str(&format!("  Your expectation     {:>8}   pre-tax annual, YOUR number and not this tool's\n", format_bps(e.annual_return_bps)));
    out.push_str(&format!("    source             {}\n", e.source));
    out.push_str(&format!("  Gains taxed at       {:>8}\n", format_bps(e.tax_bps)));
    out.push_str(&format!("  Risk premium         {:>8}", format_bps(e.risk_premium_bps)));
    if e.risk_premium_bps <= 0 {
        // Saying it plainly beats letting a zero pass as a considered choice.
        out.push_str("   ← zero treats a CERTAIN return and an uncertain one as equal. They are not.");
    }
    out.push_str("\n\n");

    out.push_str(&format!(
        "  Buffer               {:>8}   held · {}.{} months of a {} month\n",
        fm(b.liquid.minor),
        b.months_held_tenths / 10,
        b.months_held_tenths % 10,
        fm(b.monthly_need.minor)
    ));
    if b.met {
        out.push_str(&format!("                                    meets the {}-month target\n\n", b.target_months));
    } else {
        out.push_str(&format!("                                    SHORT by {} of a {}-month target\n\n", fm(b.shortfall.minor), b.target_months));
    }

    if ladder.is_empty() {
        out.push_str("  No debt is recorded, so there is nothing to weigh against investing.\n");
        out.push_str("  If that is wrong, declare the accounts: bsc fin account set\n\n");
    } else {
        out.push_str("  What each debt demands of the market\n");
        out.push_str(&format!("    {:<14} {:>11} {:>8} {:>12}   {}\n", "account", "owed", "APR", "must return", "verdict"));
        for h in ladder {
            let apr = h.apr_bps.map(format_bps).unwrap_or_else(|| "?".to_string());
            let req = h.bar_bps.map(format_bps).unwrap_or_else(|| "?".to_string());
            let verdict = match &h.verdict {
                hurdle::Verdict::RateUnknown => "RATE UNKNOWN — find it before deciding anything".to_string(),
                hurdle::Verdict::PayTheDebt { margin_bps } => format!("pay the debt — the market falls {} short", format_bps(*margin_bps)),
                hurdle::Verdict::InvestingClears { margin_bps } => format!("investing clears by {}", format_bps(*margin_bps)),
            };
            out.push_str(&format!("    {:<14} {:>11} {:>8} {:>12}   {}\n", clip(&h.account, 13), fm(h.balance.minor), apr, req, verdict));
        }
        let cost: i64 = ladder.iter().filter_map(|h| h.annual_cost.map(|c| c.minor)).sum();
        if cost > 0 {
            out.push_str(&format!("\n    Doing nothing costs {} a year in interest on the rates that are known.\n", fm(cost)));
        }
        out.push('\n');
    }

    out.push_str("  NEXT DOLLAR → ");
    match next {
        hurdle::NextDollar::BuildBuffer { shortfall } => {
            out.push_str(&format!("build the buffer. {} short.\n", fm(shortfall.minor)));
            out.push_str("    Without it the next unavoidable expense goes back on the card at the same rate —\n");
            out.push_str("    you would pay it down and borrow it again, which returns nothing.\n");
        }
        hurdle::NextDollar::FindOutTheRate { accounts } => {
            out.push_str(&format!("find out what {} charges.\n", accounts.join(" and ")));
            out.push_str("    An unknown rate is not a low one. Until it is known this cannot be ranked, and\n");
            out.push_str("    treating it as zero is how the most expensive debt gets paid last.\n");
            out.push_str("    Set it with:  bsc fin account set\n");
        }
        hurdle::NextDollar::PayDebt { account, apr_bps } => {
            out.push_str(&format!("pay down {account}.\n"));
            out.push_str(&format!("    {} guaranteed and tax-free. Nothing you have told this tool beats it.\n", format_bps(*apr_bps)));
        }
        hurdle::NextDollar::Invest => {
            out.push_str("invest.\n");
            out.push_str("    On YOUR numbers no remaining debt beats the market. That verdict is only as good\n");
            out.push_str("    as the expectation you supplied — it is an input, not a finding.\n");
        }
        hurdle::NextDollar::NothingToWeigh => out.push_str("nothing to weigh — no debt recorded and the buffer is met.\n"),
    }
    out.push_str("\n  This compares rates. It is not advice, and it does not know about your job security,\n");
    out.push_str("  your health, or anything else that ought to move the answer.\n");
    out
}

pub fn run(args: Vec<String>, prog: &str) -> Result<(), String> {
    let json = args.iter().any(|a| a == "--json");
    let positional: Vec<&String> = positional_args(&args);
    match positional.first().map(|s| s.as_str()) {
        Some("parse") => {
            let path = positional
                .get(1)
                .ok_or_else(|| format!("usage: {prog} parse <file.csv> [--json]"))?;
            let text = std::fs::read_to_string(path).map_err(|e| format!("cannot read {path}: {e}"))?;
            let p = statement::parse_csv(&text)?;
            if json {
                println!("{}", render_json(&p));
            } else {
                print!("{}", render_text(&p));
            }
            Ok(())
        }
        Some("start") => {
            let dir = inbox::inbox_dir().ok_or_else(|| "no base dir ($HOME unset)".to_string())?;
            std::fs::create_dir_all(&dir).map_err(|e| format!("cannot create {}: {e}", dir.display()))?;
            print!("{}", render_start(&dir));
            let waiting = inbox::scan(&dir)?;
            if !waiting.is_empty() {
                println!("Already waiting:");
                print!("{}", render_inbox(&waiting));
            }
            Ok(())
        }
        Some("inbox") => {
            let dir = inbox::inbox_dir().ok_or_else(|| "no base dir ($HOME unset)".to_string())?;
            let files = inbox::scan(&dir)?;
            if !args.iter().any(|a| a == "--ingest") {
                print!("{}", render_inbox(&files));
                if files.iter().any(|f| f.readable()) {
                    println!("  run `{prog} inbox --ingest` to read and claim them");
                }
                return Ok(());
            }
            let processed = inbox::processed_dir().ok_or_else(|| "no base dir ($HOME unset)".to_string())?;
            let at = session::now_iso();
            // Loaded ONCE and appended to as files are read, so two statements for the same account
            // do not both report it as undeclared.
            let (mut declared, _) = load_accounts();
            for f in &files {
                if !f.readable() {
                    println!("{} · SKIPPED, cannot tell which institution it is from", f.name);
                    continue;
                }
                let text = std::fs::read_to_string(&f.path).map_err(|e| format!("cannot read {}: {e}", f.name))?;
                match statement::parse_csv(&text) {
                    Ok(p) => {
                        print!("{}", render_text(&p));
                        // CLOSE THE LOOP. The file just told us an account exists; the registry is
                        // the only thing that can say what it IS, and nothing else will notice.
                        let id = statement::suggested_account_id(&p);
                        if account::undeclared(&declared, [id.as_str()]).is_empty() {
                            // already known
                        } else {
                            println!("  NOT DECLARED — nothing downstream can use these rows until it is:");
                            println!("    {}", declare_hint(&id, p.institution.name(), p.account_kind));
                            declared.push(Account {
                                id: id.clone(),
                                institution: p.institution.name().to_string(),
                                kind: p.account_kind,
                                currency: "USD".into(),
                                credit_limit: None,
                                apr_bps: None,
                                minimum_payment: None,
                                statement_day: None,
                                note: None,
                            });
                        }
                        // CLAIMED ONLY AFTER IT READ. A file moved out of the inbox on a parse that
                        // failed is a statement nobody will notice is missing.
                        let dest = inbox::claim(&f.path, &processed, &at)?;
                        println!("  claimed → {}", dest.display());
                    }
                    Err(e) => println!("{} · NOT READ: {e}\n  left in the inbox", f.name),
                }
            }
            Ok(())
        }
        Some("account") => {
            let (mut accounts, rejected) = load_accounts();
            match positional.get(1).map(|s| s.as_str()) {
                Some("set") => {
                    let mut raw = String::new();
                    std::io::Read::read_to_string(&mut std::io::stdin(), &mut raw)
                        .map_err(|e| format!("cannot read stdin: {e}"))?;
                    let v: serde_json::Value = serde_json::from_str(&raw).map_err(|e| format!("not JSON: {e}"))?;
                    let items = if v.is_array() { v.as_array().unwrap().clone() } else { vec![v] };
                    for item in &items {
                        account::upsert(&mut accounts, account::from_json(item)?);
                    }
                    save_accounts(&accounts)?;
                    println!("{} account(s) stored; {} known", items.len(), accounts.len());
                    Ok(())
                }
                Some("remove") => {
                    let id = positional.get(2).ok_or_else(|| format!("usage: {prog} account remove <id>"))?;
                    let before = accounts.len();
                    accounts.retain(|a| &a.id != *id);
                    if accounts.len() == before {
                        return Err(format!("{prog}: no account `{id}`"));
                    }
                    save_accounts(&accounts)?;
                    println!("removed {id}");
                    Ok(())
                }
                Some(other) if other != "list" => Err(format!("{prog}: unknown account command `{other}` — try list, set or remove")),
                _ => {
                    if json {
                        println!("{}", accounts_json(&accounts, &rejected));
                    } else {
                        print!("{}", account::render(&accounts));
                        for r in &rejected {
                            println!("  UNREADABLE ROW: {r}");
                        }
                    }
                    Ok(())
                }
            }
        }
        Some("balance") => {
            let (accounts, _) = load_accounts();
            let mut balances = load_balances();
            match positional.get(1).map(|s| s.as_str()) {
                Some("set") => {
                    let id = positional.get(2).ok_or_else(|| format!("usage: {prog} balance set <account> <printed-amount>"))?;
                    let raw = positional.get(3).ok_or_else(|| format!("usage: {prog} balance set <account> <printed-amount>"))?;
                    // WITHOUT THE KIND THE SIGN IS UNKNOWABLE, not merely unknown — storing the
                    // number unconverted would put a debt into net worth as an asset.
                    let a = accounts.iter().find(|a| &a.id == *id).ok_or_else(|| format!(
                        "{prog}: `{id}` is not a declared account, so there is no way to know whether {raw} is money you HAVE or money you OWE. Declare it first: {prog} account set"
                    ))?;
                    let minor = crate::money::parse_minor(raw)?;
                    let as_of = flag_value(&args, "--as-of").unwrap_or_else(|| session::now_iso()[..10].to_string());
                    let b = balance::from_printed(id, &as_of, crate::money::money(minor, crate::money::Currency::USD), a.kind);
                    let printed = crate::money::format_minor(minor);
                    let stored = crate::money::format_minor(b.balance.minor);
                    balance::record(&mut balances, b);
                    save_balances(&balances)?;
                    println!("{id} · statement says {printed} · stored as {stored} ({})", if a.kind.is_debt() { "owed" } else { "held" });
                    Ok(())
                }
                Some(other) if other != "list" => Err(format!("{prog}: unknown balance command `{other}` — try list or set")),
                _ => {
                    if json {
                        println!("{}", serde_json::json!({
                            "balances": balance::to_json(&balances),
                            "withoutBalance": balance::without_balance(&accounts, &balances),
                        }));
                    } else if balances.is_empty() {
                        println!("no balances recorded — `{prog} position` cannot say what anything holds until one is");
                    } else {
                        for b in balance::latest_each(&balances) {
                            println!("  {:<18} {:>12}  as of {}", b.account, crate::money::format_minor(b.balance.minor), b.as_of);
                        }
                        for m in balance::without_balance(&accounts, &balances) {
                            println!("  {m:<18}  NO BALANCE — it is absent from the position, not zero in it");
                        }
                    }
                    Ok(())
                }
            }
        }
        Some("position") => {
            let (accounts, _) = load_accounts();
            let stored = load_balances();
            let (txns, periods, mut notes) = read_all_statements()?;
            let through = txns.last().map(|t| t.date.clone()).unwrap_or_else(|| session::now_iso()[..10].to_string());
            // The statements' own closing figures ARE balances, so an export alone is enough to
            // answer — a declared account no longer has to be told what it holds. What a person
            // typed wins on the same day; see `balance::prefer_observed`.
            let balances = balance::latest_each(&balance::prefer_observed(&stored, &balance::from_periods(&periods)));
            // A REAL RECONCILE WHEN THE EXPORTS CARRIED BALANCES, and an honest unverified ledger
            // when they did not — never a reconcile that quietly passed because nothing checked it.
            let ledger = if periods.is_empty() {
                reconcile::unverified_ledger(&txns, &through, "no export carried a running balance, so there is nothing to check the transactions against")?
            } else {
                let r = reconcile::reconcile(&txns, &periods);
                match r.ledger {
                    Some(l) => l,
                    None => {
                        for p in &r.problems {
                            notes.push(format!("RECONCILE: {}", p.detail));
                        }
                        for u in &r.uncovered {
                            notes.push(format!("RECONCILE: {} on {} belongs to no statement period", u.description, u.date));
                        }
                        reconcile::unverified_ledger(&txns, &through, "the statements did NOT reconcile — see the notes below")?
                    }
                }
            };
            let p = position::position(&ledger, &accounts, &balances, crate::money::Currency::USD);
            if json {
                println!("{}", serde_json::json!({
                    "asOf": p.as_of,
                    "netWorth": p.net_worth.minor,
                    "liquid": p.liquid.minor,
                    "totalDebt": p.total_debt.minor,
                    "dailyInterest": p.daily_interest.minor,
                    "minimumsDue": p.minimums_due.minor,
                    "weightedApr": p.weighted_apr,
                    "complete": p.complete,
                    "problems": p.problems,
                    "notes": notes,
                    "accounts": p.accounts.iter().map(|a| serde_json::json!({
                        "account": a.account, "kind": a.kind.as_str(), "balance": a.balance.minor,
                        "owed": a.owed.map(|m| m.minor), "utilisation": a.utilisation,
                        "dailyInterest": a.daily_interest.map(|m| m.minor), "rolledForward": a.rolled_forward,
                    })).collect::<Vec<_>>(),
                }));
            } else {
                print!("{}", render_position(&p));
                for n in &notes {
                    println!("  · {n}");
                }
            }
            Ok(())
        }
        Some("recurring") => {
            let all = args.iter().any(|a| a == "--all");
            let as_of = flag_value(&args, "--as-of").unwrap_or_else(|| session::now_iso()[..10].to_string());
            let (txns, _, notes) = read_all_statements()?;
            let opts = recurring::DetectOptions { min_occurrences: 2, outflows_only: !all, as_of: &as_of };
            let found = recurring::detect_recurring(&txns, &opts);
            let live_total = recurring::total_annualised(&found, crate::money::Currency::USD).map_err(|e| e.to_string())?;
            if json {
                println!("{}", serde_json::json!({
                    "asOf": as_of,
                    "annualisedLive": live_total.minor,
                    "found": found.iter().map(|r| serde_json::json!({
                        "key": r.key, "label": r.label, "account": r.account,
                        "cadence": r.cadence.label(), "typical": r.typical.minor,
                        "annualised": r.annualised.minor, "occurrences": r.occurrences,
                        "firstSeen": r.first_seen, "lastSeen": r.last_seen,
                        "regularity": r.regularity, "amountStability": r.amount_stability,
                        "lapsed": r.lapsed,
                    })).collect::<Vec<_>>(),
                    "notes": notes,
                }));
            } else {
                print!("{}", render_recurring(&found, live_total, &txns, &notes));
            }
            Ok(())
        }
        Some("income") => {
            let (txns, _, notes) = read_all_statements()?;
            let a = income::analyse_income(&txns, crate::money::Currency::USD, &income::IncomeOptions::default());
            let expected = income::expected_monthly(&a, crate::money::Currency::USD).map_err(|e| e.to_string())?;
            if json {
                println!("{}", serde_json::json!({
                    "typicalMonth": a.typical_month.minor,
                    "worstMonth": a.worst_month.minor,
                    "bestMonth": a.best_month.minor,
                    "monthsObserved": a.months_observed,
                    "expectedMonthly": expected.minor,
                    "sources": a.sources.iter().map(|s| serde_json::json!({
                        "key": s.key, "label": s.label, "account": s.account,
                        "cadence": s.cadence.label(), "typical": s.typical.minor,
                        "low": s.low.minor, "high": s.high.minor, "occurrences": s.occurrences,
                        "firstSeen": s.first_seen, "lastSeen": s.last_seen,
                        "consistency": s.consistency, "stability": s.stability.label(),
                        "monthlyEquivalent": s.monthly_equivalent.minor,
                    })).collect::<Vec<_>>(),
                    "oneOff": a.one_off.iter().map(|t| serde_json::json!({
                        "date": t.date, "description": t.description, "amount": t.amount.minor,
                    })).collect::<Vec<_>>(),
                    "notes": notes,
                }));
            } else {
                print!("{}", render_income(&a, expected, &notes));
            }
            Ok(())
        }
        Some("runway") => {
            // DISCRETIONARY IS REQUIRED, not defaulted. A runway that quietly assumes groceries are
            // free is the flattering kind of wrong, and defaulting it to zero here would hide the
            // decision the module deliberately forces the caller to make.
            let Some(raw) = flag_value(&args, "--discretionary") else {
                return Err(format!(
                    "usage: {prog} runway --discretionary <amount>\n\n  What do you spend in a month OUTSIDE the standing bills — groceries, fuel, the ordinary\n  week? There is no default: a runway computed from obligations alone is not conservative,\n  it is wrong in the flattering direction. Pass 0 to say so deliberately and it will be noted."
                ));
            };
            let discretionary = crate::money::parse_minor(&raw).map_err(|e| format!("--discretionary {raw}: {e}"))?;
            let months: usize = flag_value(&args, "--months").and_then(|v| v.parse().ok()).unwrap_or(6);
            let as_of = flag_value(&args, "--as-of").unwrap_or_else(|| session::now_iso()[..10].to_string());
            let usd = crate::money::Currency::USD;

            let (accounts, _) = load_accounts();
            let stored = load_balances();
            let (txns, periods, mut notes) = read_all_statements()?;
            let balances = balance::latest_each(&balance::prefer_observed(&stored, &balance::from_periods(&periods)));
            let through = txns.last().map(|t| t.date.clone()).unwrap_or_else(|| as_of.clone());
            let ledger = if periods.is_empty() {
                reconcile::unverified_ledger(&txns, &through, "no export carried a running balance, so there is nothing to check the transactions against")?
            } else {
                let r = reconcile::reconcile(&txns, &periods);
                match r.ledger {
                    Some(l) => l,
                    None => {
                        for p in &r.problems {
                            notes.push(format!("RECONCILE: {}", p.detail));
                        }
                        reconcile::unverified_ledger(&txns, &through, "the statements did NOT reconcile")?
                    }
                }
            };
            let p = position::position(&ledger, &accounts, &balances, usd);
            let analysis = income::analyse_income(&txns, usd, &income::IncomeOptions::default());
            let projection = projection::project_income(&analysis, usd, &projection::ProjectionOptions { months, ..projection::ProjectionOptions::new(&as_of) });
            let found = recurring::detect_recurring(&txns, &recurring::DetectOptions { min_occurrences: 2, outflows_only: true, as_of: &as_of });
            // The calendar runs from the day after `as_of` to the end of the projected horizon, so
            // the two line up — a calendar shorter than the projection TRUNCATES the runway, which
            // is correct but reads as a surprise when it was merely a window nobody chose.
            let last = obligations::add_calendar_months(&format!("{}-01", crate::txn::month_of(&as_of)), months as i64 + 1);
            let cal_to = obligations::add_days(&last, -1);
            let cal = obligations::build_calendar(&found, Some(&p), &obligations::CalendarOptions::new(&as_of, &cal_to));
            let r = runway::runway(&p, &projection, &cal, &runway::RunwayOptions { discretionary: crate::money::money(discretionary, usd) });

            if json {
                println!("{}", serde_json::json!({
                    "asOf": r.as_of,
                    "startingLiquid": r.starting_liquid.minor,
                    "through": r.through,
                    "headline": {
                        "scenario": r.headline.scenario.label(),
                        "exhaustsIn": r.headline.exhausts_in,
                        "monthsOfCover": r.headline.months_of_cover,
                        "monthlyGap": r.headline.monthly_gap.minor,
                        "annualGap": runway::annual_gap(&r).minor,
                        "survives": runway::survives_horizon(&r.headline),
                        "months": r.headline.months.iter().map(|m| serde_json::json!({
                            "month": m.month, "opening": m.opening.minor, "income": m.income.minor,
                            "obligations": m.obligations.minor, "discretionary": m.discretionary.minor,
                            "net": m.net.minor, "closing": m.closing.minor,
                            "shortfall": m.shortfall.map(|s| s.minor),
                        })).collect::<Vec<_>>(),
                    },
                    "expectedMonthlyGap": r.expected.monthly_gap.minor,
                    "highMonthlyGap": r.high.monthly_gap.minor,
                    "summary": runway::summarise(&r),
                    "problems": r.problems,
                    "assumptions": projection.assumptions,
                    "notes": notes,
                }));
            } else {
                print!("{}", render_runway(&r, &projection, &cal, &notes));
            }
            Ok(())
        }
        Some("spending") => {
            let usd = crate::money::Currency::USD;
            let as_of = flag_value(&args, "--as-of").unwrap_or_else(|| session::now_iso()[..10].to_string());
            let (accounts, _) = load_accounts();
            let stored = load_balances();
            let (txns, periods, notes) = read_all_statements()?;
            let balances = balance::latest_each(&balance::prefer_observed(&stored, &balance::from_periods(&periods)));
            let through = txns.last().map(|t| t.date.clone()).unwrap_or_else(|| as_of.clone());
            let ledger = reconcile::unverified_ledger(&txns, &through, "spending is computed over what was read, whether or not it reconciled")?;
            let p = position::position(&ledger, &accounts, &balances, usd);
            let found = recurring::detect_recurring(&txns, &recurring::DetectOptions { min_occurrences: 2, outflows_only: true, as_of: &as_of });
            let a = spending::analyse_spending(&ledger, Some(&p), &found, usd, &spending::SpendingOptions::default());
            if json {
                println!("{}", serde_json::json!({
                    "from": a.from, "to": a.to, "monthsObserved": a.months_observed,
                    "fixedMonthly": a.fixed_monthly.minor,
                    "variableMonthly": a.variable_monthly.minor,
                    "discretionaryMonthly": spending::discretionary_monthly(&a).minor,
                    "transferred": a.transferred.minor, "transferCount": a.transfer_count,
                    "debtPayments": a.debt_payments.minor,
                    "categories": a.categories.iter().map(|c| serde_json::json!({
                        "category": c.category, "total": c.total.minor,
                        "count": c.count, "typicalMonth": c.typical_month.minor,
                    })).collect::<Vec<_>>(),
                    "uncategorised": a.uncategorised.iter().map(|t| serde_json::json!({
                        "date": t.date, "description": t.description, "amount": t.amount.minor,
                    })).collect::<Vec<_>>(),
                    "notes": a.notes, "readNotes": notes,
                }));
            } else {
                print!("{}", render_spending(&a, &notes));
            }
            Ok(())
        }
        Some("payoff") => {
            // The BUDGET is required for the same reason runway's discretionary is: there is no
            // sensible default for what somebody can pay, and guessing one produces a schedule that
            // looks authoritative and describes nobody.
            let Some(raw) = flag_value(&args, "--budget") else {
                return Err(format!(
                    "usage: {prog} payoff --budget <amount>\n\n  What can you put toward debt in a month, IN TOTAL including the minimums? Both\n  strategies are run against it and the difference is reported — this does not pick."
                ));
            };
            let budget = crate::money::parse_minor(&raw).map_err(|e| format!("--budget {raw}: {e}"))?;
            let usd = crate::money::Currency::USD;
            let (accounts, _) = load_accounts();
            let stored = load_balances();
            let (txns, periods, notes) = read_all_statements()?;
            let balances = balance::latest_each(&balance::prefer_observed(&stored, &balance::from_periods(&periods)));
            let through = txns.last().map(|t| t.date.clone()).unwrap_or_else(|| session::now_iso()[..10].to_string());
            let ledger = reconcile::unverified_ledger(&txns, &through, "a payoff schedule is computed from the declared debts, not from the transactions")?;
            let p = position::position(&ledger, &accounts, &balances, usd);

            // A debt with no APR cannot be scheduled — the interest is the whole mechanism — and a
            // debt with no minimum cannot either. Both are NAMED rather than silently dropped.
            let mut debts: Vec<payoff::Debt> = Vec::new();
            let mut skipped: Vec<String> = Vec::new();
            for a in &p.accounts {
                if !a.is_debt {
                    continue;
                }
                match (a.owed, a.apr, a.minimum_payment) {
                    (Some(owed), Some(apr), Some(minimum)) if owed.minor > 0 => {
                        debts.push(payoff::Debt { name: a.account.clone(), balance: owed, apr, minimum });
                    }
                    (owed, apr, minimum) => {
                        let mut missing: Vec<&str> = Vec::new();
                        if owed.is_none_or(|o| o.minor <= 0) { missing.push("a balance owed"); }
                        if apr.is_none() { missing.push("an APR"); }
                        if minimum.is_none() { missing.push("a minimum payment"); }
                        if !missing.is_empty() {
                            skipped.push(format!("{} is NOT in this schedule — it is missing {}; set it with `{prog} account set`", a.account, missing.join(" and ")));
                        }
                    }
                }
            }

            if debts.is_empty() {
                let mut out = String::from("no debt can be scheduled yet\n");
                for s in &skipped {
                    out.push_str(&format!("  · {s}\n"));
                }
                for n in &notes {
                    out.push_str(&format!("  · {n}\n"));
                }
                print!("{out}");
                return Ok(());
            }

            let c = payoff::compare_strategies(&debts, crate::money::money(budget, usd), &payoff::PayoffOptions::default())
                .map_err(|e| e.0)?;
            if json {
                let plan = |p: &payoff::Plan| serde_json::json!({
                    "strategy": p.strategy.label(), "months": p.months,
                    "totalInterest": p.total_interest.minor, "totalPaid": p.total_paid.minor,
                    "order": p.order,
                });
                println!("{}", serde_json::json!({
                    "avalanche": plan(&c.avalanche), "snowball": plan(&c.snowball),
                    "extraInterest": c.extra_interest.minor, "extraMonths": c.extra_months,
                    "firstClearedSooner": c.first_cleared_sooner,
                    "skipped": skipped, "notes": notes,
                }));
            } else {
                print!("{}", render_payoff(&c, &skipped, &notes));
            }
            Ok(())
        }
        Some("viable") => {
            let usd = crate::money::Currency::USD;
            let as_of = flag_value(&args, "--as-of").unwrap_or_else(|| session::now_iso()[..10].to_string());
            let months: usize = flag_value(&args, "--months").and_then(|v| v.parse().ok()).unwrap_or(6);
            let progress = flag_value(&args, "--progress").map(|v| crate::money::parse_minor(&v)).transpose().map_err(|e| format!("--progress: {e}"))?.unwrap_or(0);
            let a = analysis(&as_of)?;
            let found = recurring::detect_recurring(&a.txns, &recurring::DetectOptions { min_occurrences: 2, outflows_only: true, as_of: &as_of });
            let last = obligations::add_calendar_months(&format!("{}-01", crate::txn::month_of(&as_of)), months as i64 + 1);
            let cal_to = obligations::add_days(&last, -1);
            let cal = obligations::build_calendar(&found, Some(&a.position), &obligations::CalendarOptions::new(&as_of, &cal_to));
            let sp = spending::analyse_spending(&a.ledger, Some(&a.position), &found, usd, &spending::SpendingOptions::default());
            let analysis_income = income::analyse_income(&a.txns, usd, &income::IncomeOptions::default());
