                Some(raw) => Some(crate::money::parse_minor(&raw).map_err(|e| format!("--income-rate {raw}: {e}"))?),
            };

            let (from, to) = (format!("{year}-01-01"), format!("{year}-12-31"));
            let (invoices, rejected) = load_invoices();
            for r in &rejected {
                eprintln!("invoices.json: {r}");
            }
            // Revenue is CASH BASIS — what arrived — because that is what a sole proprietor almost
            // always files on, and `bsc fin invoice revenue` reports both if the other is wanted.
            let credits = analysis(&to).map(|a| a.txns).unwrap_or_default();
            let m = invoice::match_payments(&invoices, &credits, &invoice::MatchOptions::default());
            let rev = invoice::revenue(&invoices, &m, &from, &to, usd);

            let y = taxyear::assemble(year, status, rev.cash_basis, expenses, income_bps, &p);
            let harbour = taxyear::safe_harbour(&y.se);
            if json {
                println!("{}", serde_json::json!({
                    "year": y.year,
                    "status": y.status.key(),
                    "revenueMinor": y.revenue.minor,
                    "accrualRevenueMinor": rev.accrual_basis.minor,
                    "expensesMinor": y.expenses.minor,
                    "expensesDeclared": (y.expense_basis == taxyear::ExpenseBasis::Declared),
                    "netProfitMinor": y.net_profit.minor,
                    "selfEmployment": {
                        "netEarningsMinor": y.se.net_earnings.minor,
                        "socialSecurityMinor": y.se.social_security.minor,
                        "medicareMinor": y.se.medicare.minor,
                        "additionalMedicareMinor": y.se.additional_medicare.minor,
                        "totalMinor": y.se.total.minor,
                        "deductibleHalfMinor": y.se.deductible_half.minor,
                        "wageBaseBound": y.se.cap_bound,
                    },
                    "setAsideMinor": y.set_aside.map(|a| a.minor),
                    "safeHarbourMinor": harbour.0.minor,
                    "incomeTaxComputed": false,
                    "checkedByAPerson": false,
                    "wageBaseSource": p.source,
                    "notes": y.se.notes.iter().chain(y.notes.iter()).collect::<Vec<_>>(),
                }));
            } else {
                print!("{}", render_tax(&y, &p, harbour));
                // The evidence for the judgement this cannot make. Shown AFTER the report so it
                // reads as candidates to sort through, never as a deduction already taken.
                if y.expense_basis == taxyear::ExpenseBasis::Absent {
                    if let Ok(a) = analysis(&to) {
                        let found = recurring::detect_recurring(&a.txns, &recurring::DetectOptions { min_occurrences: 2, outflows_only: true, as_of: &to });
                        let sp = spending::analyse_spending(&a.ledger, Some(&a.position), &found, usd, &spending::SpendingOptions::default());
                        let top = spending::top_categories(&sp, 8);
                        if !top.is_empty() {
                            println!("\n  Candidates for --expenses, from your statements. NONE of this is claimed:");
                            for c in top {
                                println!("    {:<28} {:>12}", clip(c.category, 27), crate::money::format_minor(c.total.minor.abs()));
                            }
                            println!("    Business or personal is a judgement no bank line can make, and this has not");
                            println!("    tried. Add up the ones that are genuinely business costs and pass the total.");
                        }
                    }
                }
            }
            Ok(())
        }
        Some("session") => {
            let mut states = load_states();
            let connectors: Vec<&str> = inbox::KNOWN.to_vec();
            match positional.get(1).map(|s| s.as_str()) {
                Some(id) if args.iter().any(|a| a == "--established") => {
                    if !connectors.contains(&id) {
                        return Err(format!("{prog}: `{id}` is not a known institution — try one of: {}", connectors.join(", ")));
                    }
                    let mut state = session::state_for(&states, id);
                    session::established(&mut state, &session::now_iso());
                    session::upsert(&mut states, state);
                    save_states(&states)?;
                    println!("{id} · session recorded — unattended fetches may reuse it until it ages out");
                    Ok(())
                }
                Some(id) => Err(format!(
                    "usage: {prog} session {id} --established  # after signing in by hand"
                )),
                None => {
                    print!("{}", render_sessions(&states, &connectors, &session::now_iso()));
                    Ok(())
                }
            }
        }
        // The offer is BUILT FROM `COMMANDS`, not typed out beside it. A hand-written list is a
        // second place to remember, and the test over `COMMANDS` caught it going stale the first
        // time a verb was added — so the fix is to remove the second place rather than update it.
        Some(other) => Err(format!("{prog}: unknown command `{other}` — try {}", verb_list(prog))),
        None => Err(format!(
            "usage: {prog} <{}>",
            COMMANDS.iter().map(|c| c.name).collect::<Vec<_>>().join("|")
        )),
    }
}

