    fn the_ledger_puts_the_decision_above_the_settled_rows() {
        let usd = crate::money::Currency::USD;
        let (invoices, credits) = inv_fixture();
        let m = invoice::match_payments(&invoices, &credits, &invoice::MatchOptions::default());
        let s = invoice::settle(&invoices, &m, usd);
        let b = invoice::age(&s, &invoices, "2026-07-10", usd);
        let out = render_invoices(&s, &b, &m, &[], "2026-07-10");

        // The ambiguous credit is NAMED with both candidates rather than silently assigned.
        assert!(out.contains("NEEDS A DECISION"), "{out}");
        assert!(out.contains("INV-014 or INV-015"), "{out}");
        // And it appears BEFORE the settled rows — a decision buried under a list stops being made.
        let decision = out.find("NEEDS A DECISION").expect("decision block");
        let owed = out.find("  Owed").expect("owed block");
        assert!(decision < owed, "the decision must come first");

        // The referenced one matched, so it is not owed and not in the ageing table.
        assert!(!out.contains("INV-016"), "a paid invoice appears nowhere in the ledger: {out}");
        // The 90+ bucket is not reached by an invoice due three weeks ago.
        assert!(out.contains("1-30"), "{out}");
        assert!(!out.contains("90+"), "{out}");
        // Money that belongs to no invoice is reported rather than absorbed.
        assert!(out.contains("Arrived, belongs to no invoice"), "{out}");
        assert!(out.contains("REFUND FROM SOMEWHERE"), "{out}");
    }

