        let out = render_where(&chain, &obs, &sales, &income, "2026-09-04");

        // The stack reads outermost-in, the way an address does.
        assert!(out.starts_with("United States › Georgia › Gwinnett County › Duluth"), "{out}");
        // The combined rate AND what it is made of — 4% state plus 2% county is the check a person
        // can actually perform against a rate chart.
        assert!(out.contains("6.00%"), "{out}");
        assert!(out.contains("us/ga/gwinnett 2.00%") && out.contains("us/ga 4.00%"), "{out}");
        // Georgia's income rate has LAPSED for this date, so the line says so rather than showing
        // last year's number. This is the behaviour the whole module exists for.
        assert!(income.is_empty());
        assert!(out.contains("income tax       NOT KNOWN"), "{out}");
        // The city licence is present with an authority to call.
        assert!(out.contains("Occupational tax certificate"), "{out}");
        assert!(out.contains("City of Duluth"), "{out}");
        // And the standing caveat is not optional.
        assert!(out.contains("NOTHING HERE HAS BEEN CHECKED"), "{out}");
        assert!(out.contains("not\n  tax advice"), "{out}");
    }

