        // The usage line is built FROM `COMMANDS`, so this pins that the verb is reachable rather
        // than that a hand-written list happens to mention it.
        assert!(COMMANDS.iter().any(|c| c.name == "invoice"));
        assert!(verb_list("bsc fin").contains("invoice"));
    }

    // SYNTHETIC FIXTURES ONLY. No real statement, balance or account number belongs in this repo.
    fn parsed(txns: Vec<Txn>, rejected: Vec<Rejected>) -> Parsed {
        Parsed { institution: Institution::Discover, profile: "discover-card", account_kind: crate::account::Kind::Credit, txns, rejected, period: None }
    }

    fn txn(date: &str, description: &str, minor: i64) -> Txn {
        Txn { date: date.to_string(), description: description.to_string(), minor }
    }

    fn rejected(line: usize, reason: &str) -> Rejected {
        Rejected { line, reason: reason.to_string() }
    }

    #[test]
    fn text_render_names_every_unread_row_not_just_a_count() {
        // A count alone tells you the total is wrong without telling you where to look, and a number
        // that is wrong by an unknown amount is not usable for anything.
        let p = parsed(
            vec![txn("2026-06-03", "SAFEWAY", -8410)],
            vec![rejected(7, "'n/a' is not an amount"), rejected(12, "3 columns, expected 5")],
        );
        let out = render_text(&p);
        assert!(out.contains("2 row(s) NOT read"), "{out}");
        assert!(out.contains("line 7: 'n/a' is not an amount"), "{out}");
        assert!(out.contains("line 12: 3 columns, expected 5"), "{out}");
    }

    #[test]
    fn text_render_says_so_plainly_when_nothing_was_missed() {
        let out = render_text(&parsed(vec![txn("2026-06-03", "SAFEWAY", -8410)], vec![]));
        assert!(out.contains("every row read"), "{out}");
        assert!(!out.contains("NOT read"), "{out}");
    }

    #[test]
    fn text_render_nets_the_signs_rather_than_the_magnitudes() {
        // -84.10 and +300.00 net to +215.90. Summing magnitudes would give 384.10, which is not a
        // quantity that means anything.
        let p = parsed(
            vec![txn("2026-06-03", "SAFEWAY", -8410), txn("2026-06-05", "PAYMENT", 30000)],
            vec![],
        );
        let out = render_text(&p);
        assert!(out.contains("net 215.90"), "{out}");
        assert!(out.contains("2 transaction(s)"), "{out}");
    }

