    fn text_render_names_the_institution_and_the_profile_it_matched() {
        // Which profile matched IS the answer to "why did it read the columns that way".
        let out = render_text(&parsed(vec![], vec![]));
        assert!(out.contains("discover"), "{out}");
        assert!(out.contains("discover-card"), "{out}");
    }

    #[test]
    fn json_render_carries_every_rejection_alongside_every_transaction() {
        // A consumer that only saw `transactions` would compute a total off a file it did not know
        // was short — the same failure the text render exists to prevent, in the other direction.
        let p = parsed(
            vec![txn("2026-06-03", "SQUARE, INC", -1250)],
            vec![rejected(4, "'' is not an amount")],
        );
        let v = render_json(&p);
        assert_eq!(v["institution"], "discover");
        assert_eq!(v["profile"], "discover-card");
        assert_eq!(v["transactions"].as_array().unwrap().len(), 1);
        assert_eq!(v["transactions"][0]["description"], "SQUARE, INC");
        assert_eq!(v["transactions"][0]["minor"], -1250);
        assert_eq!(v["rejected"].as_array().unwrap().len(), 1);
        assert_eq!(v["rejected"][0]["line"], 4);
    }

    #[test]
    fn json_render_keeps_rejected_as_an_empty_array_never_absent() {
        // An absent key reads as "unknown" to a consumer; an empty array reads as "none". They are
        // different claims and only one of them is true here.
        let v = render_json(&parsed(vec![], vec![]));
        assert!(v["rejected"].is_array());
        assert_eq!(v["rejected"].as_array().unwrap().len(), 0);
        assert!(v["transactions"].is_array());
    }

    #[test]
    fn json_render_keeps_the_minor_units_as_an_integer() {
        // A float here would put the defect class this whole crate avoids back into the wire format.
        let v = render_json(&parsed(vec![txn("2026-06-03", "X", -8410)], vec![]));
        assert!(v["transactions"][0]["minor"].is_i64());
    }

