    #[test]
    fn the_declare_hint_is_a_command_not_a_description_of_one() {
        // An agent driving this has no hands to go and look up field names, and the gap between
        // "you should declare this" and a pasteable line is where the loop actually breaks.
        let h = declare_hint("chase-credit", "chase", crate::account::Kind::Credit);
        assert!(h.starts_with("echo '{"), "{h}");
        assert!(h.ends_with("| bsc fin account set"), "{h}");
        assert!(h.contains("\"kind\":\"credit\""), "{h}");
        assert!(h.contains("\"id\":\"chase-credit\""), "{h}");
        // and it must actually parse back into an account
        let json = h.trim_start_matches("echo '").split("' |").next().unwrap();
        let a = crate::account::from_json(&serde_json::from_str(json).unwrap()).unwrap();
        assert_eq!(a.id, "chase-credit");
        assert_eq!(a.kind, crate::account::Kind::Credit);
    }

